import br.cofra.studio.rtmp.*;import java.io.*;import java.nio.file.*;import java.util.*;
public class PublishFlv {
 public static void main(String[] args)throws Exception{final String[] error={null};RtmpClient client=new RtmpClient(s->error[0]=s);try{client.connect(new Endpoint(args[0],args[1]),320,568,15,true,2,48000);byte[] b=Files.readAllBytes(Paths.get(args[2]));int p=13;long begin=System.nanoTime();int tags=0;while(p+15<=b.length){int type=b[p]&255,n=(b[p+1]&255)<<16|(b[p+2]&255)<<8|b[p+3]&255,ts=(b[p+7]&255)<<24|(b[p+4]&255)<<16|(b[p+5]&255)<<8|b[p+6]&255;p+=11;if(n<0||p+n+4>b.length)throw new IOException();while((System.nanoTime()-begin)/1000000<ts)Thread.sleep(2);byte[] data=Arrays.copyOfRange(b,p,p+n);if(type==9){client.offerVideo(data,ts);tags++;}else if(type==8){client.offerAudio(data,ts);tags++;}p+=n+4;if(error[0]!=null)throw new IOException(error[0]);}Thread.sleep(500);if(error[0]!=null)throw new IOException(error[0]);System.out.println("{\"ok\":true,\"tags\":"+tags+",\"frames\":"+client.videoFrames+",\"sentBytes\":"+client.sentBytes+"}");}finally{client.close();}}
}
